"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Razmak od početka / kraja čini od prirubnice djelimičnu prirubnicu. Dodatni zatvoreni profili u skici postaju izrezi u ploči. Rupe i prozori u prirubnici: sredina duž ivice (kod zakrivljene ivice duž luka), sredina od kraja savijanja, veličina – pojavljuju se i u razvijenom obliku. Ako zakrivljena ivica bez prijeloma prelazi u susjednu ivicu i obje imaju prirubnicu s istim uglom savijanja, prirubnice prelaze jedna u drugu bez oslobodnog izreza. „Kontura iz skice“ izrezuje zatvorene profile skice iz prirubnice: njen X ide duž ivice, njen Y u prirubnicu, nulta tačka leži na početku ivice na kraju savijanja (može se pomjerati).",
