"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Vratiti sve postavke, prilagodbe alatne trake i vlastite prečace na zadane vrijednosti?\n\nVlastite biblioteke alata, materijali i predlošci ostaju sačuvani.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Odaberite sve plohe karakteristike: kod rupe zid (i upuštanje, dno), kod džepa zidove i dno, kod čepa omotač i čeonu plohu. Karakteristika se pomjera za X/Y/Z; staro mjesto se zatvara. Radi i kod uvezenih STEP dijelova bez historije. Prvi put se učitava veliko geometrijsko jezgro (nekoliko sekundi).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Odaberite sve plohe koje trebaju nestati (kod džepa zidove i dno, kod rupe zid, kod zaobljenja zaobljenu plohu). Susjedne plohe se produžavaju preko praznine. Korak se preračunava pri izmjenama tijela; prvi put se za to učitava veliko geometrijsko jezgro (nekoliko sekundi).",
