"Deckkraft der Fenster":"Neprozirnost prozora",
"Den Parameter benutzen: einen Schritt der Zeitleiste öffnen (Doppelklick, z. B. die Extrusion) und als Abstand =dicke eintippen.":"Koristite parametar: otvorite korak vremenske linije (dvoklik, npr. ekstruziju) i kao udaljenost upišite =dicke.",
"Den Schlüssel wie ein Kennwort behandeln: Wer ihn hat und auf diesem Rechner läuft, kann den geöffneten Entwurf ändern. Der Anschluss bleibt nur offen, solange WerkFab läuft.":"Ključ tretirajte kao lozinku: ko ga ima i radi na ovom računaru, može mijenjati otvoreni nacrt. Port ostaje otvoren samo dok WerkFab radi.",
"Den Wert ändern (z. B. 20) und eine zweite Variante speichern – in der Konfigurationstabelle lassen sich beide umschalten und als Teilefamilie exportieren.":"Promijenite vrijednost (npr. 20) i spremite drugu varijantu – u tabeli konfiguracija mogu se prebacivati obje i izvesti kao porodica dijelova.",
"Der Ablauf hat noch keine Dauer – Schritte mit Dauer anlegen.":"Tok još nema trajanje – kreirajte korake s trajanjem.",
"Der Anschluss antwortet nicht.":"Port ne odgovara.",
"Der Durchmesser ist kleiner als die doppelte Wanddicke":"Prečnik je manji od dvostruke debljine zida",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Prečnik bi postao nula ili negativan – smanjite razmak",
"Der Geometriekern konnte dieses Feature nicht berechnen – Maße und gewählte Kanten oder Flächen prüfen.":"Geometrijsko jezgro nije moglo izračunati ovu značajku – provjerite mjere i odabrane ivice ili površine.",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Glodalo za navoje radi u punom materijalu: prethodno oslobodite čep glodanjem (2D kontura izvana oko čepa do dubine navoja).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Tijelo na ovoj ravni nema obris.",
"Der Körper hat keine ebene Fläche":"Tijelo nema ravnu plohu",
"Der Körper ist zu dick für ein Blech":"Tijelo je predebelo za lim",
"Der Körper muss überall gleich dick sein – gezeichnet, extrudiert oder aus einer STEP-Datei. Erkannt werden die Blechdicke (Abstand der größten Fläche zu ihrer Gegenfläche), die ebenen Wände und die Biegungen dazwischen mit Winkel und Innenradius, rund oder scharfkantig. Daraus entsteht die Abwicklung; als Blech liegt sie als Skizze mit Biegelinien vor und lässt sich wie jedes Blech ändern, abwickeln und schachteln. Der K-Faktor bestimmt die gestreckten Längen. Zeigt die größte Fläche nach oben oder unten, liegt das Blech genau im Körper, sonst flach auf der XY-Ebene. Säume (180°) und gerundete Wände zwischen zwei ebenen Wänden werden als Biegung mit eigenem Radius übernommen. Nicht erkannt werden frei endende gerollte Ränder, Rohre und Umformungen wie Sicken.":"Tijelo mora svuda biti jednake debljine – nacrtano, ekstrudirano ili iz STEP datoteke. Prepoznaju se debljina lima (udaljenost najveće plohe od njoj suprotne plohe), ravni zidovi i savijanja među njima s uglom i unutrašnjim radijusom, zaobljena ili oštrobridna. Iz toga nastaje razvijeni oblik; kao lim postoji kao skica sa linijama savijanja i može se mijenjati, razvijati i slagati kao svaki lim. K-faktor određuje razvijene dužine. Ako najveća ploha gleda prema gore ili dolje, lim leži tačno u tijelu, inače ravno na ravni XY. Pregibi (180°) i zaobljeni zidovi između dva ravna zida preuzimaju se kao savijanje s vlastitim radijusom. Ne prepoznaju se slobodno završeni valjani rubovi, cijevi i oblikovanja poput ukruta.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Tijelo se preuzima kao mreža s trouglovima prikaza. Samo tijelo ostaje sačuvano; kasnije izmjene tijela ne mijenjaju mrežu.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Tijelo se skenira oko svoje okomite središnje ose i sprema kao kontura držača (segmenti) u biblioteku alata dokumenta.",
"Der Link enthält kein Design.":"Link ne sadrži dizajn.",
"Der Link ist unvollständig oder beschädigt (beim Kopieren abgeschnitten?).":"Link je nepotpun ili oštećen (odsječen pri kopiranju?).",
"Der Nahtspalt ist größer als der Umfang":"Razmak šava veći je od obima",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Tačka oko koje se pogled rotira (kod slobodnog orbita). „Ispod pokazivača miša“: mjesto na modelu na kojem počinje rotacija.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Polumjer ravnomjerno raste od početka do kraja svake odabrane ivice. Koji je kraj početak određuje ivica – po potrebi zamijenite.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Rub plohe je zatvoren lanac: s opcijom „neprekidno“ polumjer se mijenja jednom oko cijelog ruba, a bez te opcije na svakoj ivici zasebno od početnog do krajnjeg polumjera.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Rez ne pogađa nijedno tijelo – materijal se ne uklanja.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Tekst se nalazi kao komentar na ovom mjestu u programu.",
"Der alte Schlüssel gilt dann nicht mehr; verbundene Agenten müssen neu eingerichtet werden":"Stari ključ tada više ne vrijedi; povezani agenti se moraju ponovo podesiti",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Prva udaljenost mjeri se na plohi koja je više okrenuta prema gore (Z), druga udaljenost odnosno ugao odnosi se na drugu plohu. „Zamijeni strane“ to obrće. Tangencijalno povezane ivice prate se zajedno.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Odabrano tijelo je pripremak (npr. odlivak ili otkivak). Ono samo se ne obrađuje.",
"Der große Geometriekern ist noch nicht geladen":"Veliko geometrijsko jezgro još nije učitano",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Veliko geometrijsko jezgro se učitava – ovaj korak će se odmah sam preračunati",
