"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Pretvori zatvorenu mrežu u zapreminsko tijelo (svaki trougao postaje ploha)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Okruglo glodalo ostavlja svoj radijus u svakom unutrašnjem uglu – ugaoni protudio tada ne stane. Odmak se na svakom oštrom unutrašnjem uglu nakratko uvlači u ugao i vraća.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Povezani agent radi na otvorenom nacrtu: čita i mijenja vremensku liniju, upituje tijela, zapreminu i greške, preuzima standardne dijelove iz kataloga dijelova, dobija sliku prikaza, izvozi STEP ili STL, kreira alate i proizvodne operacije te ispisuje NC program – koji se i dalje mora provjeriti prije prvog reza. Nema pristup datotekama, postavkama ni drugim nacrtima. Svaka promjena je jedan korak koji Ctrl+Z poništava.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Drugi klik na dugme alata za crtanje vraća na Odabir",
