"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Postavite rupu: „Rupa“ (H), kliknite gornju plohu, odaberite prečnik, OK. (Ekstruzija s „Izreži“ se također računa.)",
