"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Stvara novu plohu na udaljenosti od odabranih ploha (negativno = prema unutra). Tijelo ostaje nepromijenjeno.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Stvara ciklus ticanja (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
"Es braucht einen Körper – falls keiner da ist: Datei → Beispiele, oder zuerst „Erstes Teil“.":"Potrebno je tijelo – ako ga nema: Datoteka → Primjeri, ili prvo „Prvi dio“.",
