"Fläche am bewegten Körper gewählt":"Ploha na pokretnom tijelu odabrana",
"Fläche anklicken – die Bohrung entsteht mit":"Kliknite površinu – rupa nastaje istovremeno",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Kliknite površinu: u svakoj tački klika nastaje prolazna rupa za vijak (ISO 273, srednji niz) kroz sve dijelove koji tamo leže jedan na drugom – za vijke s upuštenom glavom s 90° konusnim upuštanjem, za vijke s cilindričnom glavom po želji s cilindričnim upuštanjem (DIN 974-1, niz 1) dubokim koliko i glava. Vijak odmah sjedi u rupi. Rupa i vijak se poslije mogu mijenjati na vremenskoj liniji.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Kliknite plohu tijela: njen rub ulazi u skicu kao kontura. Klik na ivicu projicira samo tu ivicu (krugovi ostaju krugovi). Projicirana geometrija je ljubičasta.",
"Fläche ersetzen":"Zamijeni plohu",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Zamijeni plohu: postavi ravnu plohu na drugu ravan – tijelo raste ili se skraćuje",
"Fläche extrudieren":"Ekstrudiranje plohe",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Površina iza prozora – vrijedi kada je gore odabran dizajn „Vlastiti“",
"Fläche löschen":"Obriši plohu",
