"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Pomjeri plohu: pomjeranje ravnih ploha, promjena prečnika rupa i čepova",
"Fläche wählen":"Odaberite površ",
"Fläche wählen, die getrimmt wird":"Odaberite plohu koja se podrezuje",
"Fläche zum Antasten in Z":"Ploha za diranje po Z",
