"Flächen am Körper":"Plohe na tijelu",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Plohe na kraju dijela (dvoploh, četverokut, šesterokut) pogonjenim vretenastim glodalom duž Z. Širina ključa = dvostruka udaljenost plohe od ose rotacije. X i C se kreću zajedno (polarna interpolacija, Fanuc G12.1); bez ovog predloška u postprocesoru izlaze kratki X/C koraci.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Kliknite plohe koje se zadebljavaju (ponovni klik uklanja).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Kliknite na ravni koje se nagibaju (ponovni klik uklanja).",
"Flächen anklicken, die offen sein sollen.":"Kliknite na plohe koje trebaju biti otvorene.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Kliknite plohe koje se pomiču (ponovni klik uklanja).",
"Flächen im Modell":"Plohe u modelu",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Plohe sa zajedničkim ivicama spajaju se u jednu. Ako je omotač potpuno zatvoren, nastaje volumensko tijelo (zatim se normalno dalje obrađuje). Praznine veće od tolerancije ostaju otvorene.",
