"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 datoteke (.f3d) su zatvoreni Autodesk format i ne mogu se čitati.\n\nU Fusion 360: odaberite Datoteka → Izvezi → STEP (.stp) i uvezite tu datoteku ovdje.",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Postprocesor Fusion 360 „{0}“ preuzet:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Prelazi sve oštre vanjske ivice dostupne odozgo i lomi ih za dubinu skidanja srha – glodalom za skošenje kao skošenje (osa alata okomita, vrh izvan ivice), kuglastim/lollipop glodalom zaobljeno.",
"Führungszapfen-Ø":"Ø vodećeg zatika",
"Für 2D-Fase einen Fasenfräser (V) wählen":"Za 2D skošenje odaberite glodalo za skošenje (V)",
