"Für Dateien aus Programmen, in denen Y nach oben zeigt: das Netz wird aufgerichtet und auf Z = 0 gestellt":"Za datoteke iz programa u kojima Y pokazuje prema gore: mreža se uspravlja i postavlja na Z = 0",
