"Für Setups, die nicht von oben bearbeitet werden":"Za setupe koji se ne obrađuju odozgo",
"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"Za Sweep je potrebna putanja: otvorena linija u skici (završite tipkom Enter).",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Za touchpade: skrolanje pomjera pogled, razmicanje prstiju (ili Ctrl + kotačić miša) zumira",
"Für V-Gravur einen Fasenfräser (V) wählen":"Za V-graviranje odaberite glodalo za skošenje (V)",
"Für den Steuerungszyklus entlang einer Linie die Nutbreite angeben":"Za ciklus upravljanja duž linije navedite širinu utora",
"Für diese Strategie nicht geeignet":"Nije prikladno za ovu strategiju",
"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Za rupu Ø {0} mm u ovoj seriji nema odgovarajućeg vijka.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Za kose smjerove kreirajte konstrukcijsku osu (kroz dvije tačke, cilindar ili dvije ravni) – ona se tada pojavljuje ovdje kao smjer.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Za trohoidalno glodanje duž linije unesite širinu žljeba",
"Für {0} ist kein Gewinde hinterlegt.":"Za {0} nije pohranjen navoj.",
