"Gelenk":"Zglob",
"Gelenk: 1. Komponente (wird bewegt) – Bohrung, Zapfen oder Fläche anklicken.":"Zglob: 1. komponenta (pomiče se) – kliknite na rupu, osovinicu ili plohu.",
"Gelenk: 2. Komponente (Bezug) – Bohrung, Zapfen oder Fläche anklicken.":"Zglob: 2. komponenta (referenca) – kliknite na rupu, osovinicu ili plohu.",
