"Geometriekern nicht geladen":"Geometrijsko jezgro nije učitano",
"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"Geometrijska jezgra: OpenCascade (preko replicad) · Prikaz: three.js · Postavke se spremaju na ovom računaru.",
"Geometriekern: {0}":"Geometrijsko jezgro: {0}",
"Georgia (Serifen)":"Georgia (serifni)",
"Geprüft – stimmt":"Provjereno – ispravno",
"Gerade (radial)":"Ravno (radijalno)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Prave linije skice koje ne pripadaju nijednom profilu (i pomoćne linije). Savijanje: linija je sredina zone savijanja, a skica je tamo kroj – najveći komad ploče ostaje na mjestu, sve s druge strane linije zakreće se sa svojim prirubnicama. Linija vrijedi preko cijele ploče. Ukrutno rebro: rebro duž linije, okruglo u presjeku i na krajevima; lim zadržava svoju debljinu.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Ravni utori (izduženi otvor ili linija sa širinom utora) izlaze kao ciklus utora upravljanja.",
"Geraden, Bögen und Kreise":"Linije, lukovi i krugovi",
"Gerader Teil (nach der Biegung)":"Ravni dio (nakon savijanja)",
"Geradheit":"Pravost",
"Geradlinig":"Pravolinijski",
"Gerät":"Uređaj",
"Gerät per USB oder Funkempfänger anschließen":"Povežite uređaj putem USB-a ili bežičnog prijemnika",
"Gesamtabstand":"Ukupni razmak",
"Gesamte Bearbeitungszeit":"Ukupno vrijeme obrade",
"Gesamte Rechenzeit":"Ukupno vrijeme proračuna",
"Gesamtes axiales Rohteilaufmaß":"Ukupni aksijalni dodatak pripremka",
"Gesamtes radiales Rohteilaufmaß":"Ukupni radijalni dodatak pripremka",
"Gesamtlänge":"Ukupna dužina",
"Gesamtwinkel":"Ukupni ugao",
"Gesamtzeit":"Ukupno vrijeme",
"Gesamtzeit ca. {0}":"Ukupno vrijeme oko {0}",
"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Uspjeli ste! Dio je u vremenskoj liniji dolje – dvoklik na korak ga naknadno mijenja. Nastavite s „Mjere kao parametri“ ili „Od dijela do NC programa“.",
"Geschlossen":"Zatvoreno",
"Geschlossen (Gehrung)":"Zatvoreno (kosi spoj)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Zatvoreno: kraci na dvije susjedne ivice idu do simetrale ugla i tamo ostavljaju zazor. Rasterećenje ugla nalazi se tamo gdje se zone savijanja presijecaju – u razvijenom i u savijenom dijelu. I krak na zakrivljenoj ivici se na pravom uglu reže na gerung (tamo bez rasterećenja ugla).",
"Geschlossene Kette {0}":"Zatvoreni lanac {0}",
"Geschlossene Profile begrenzen den Bereich.":"Zatvoreni profili ograničavaju područje.",
