"Gewinde als ein Zyklus-Satz: Okuma G71 (gerade Zustellung B0, Gewindetiefe H, erste Zustellung D), Fanuc G76 (Flankenzustellung 60°).":"Navoj kao jedan blok ciklusa: Okuma G71 (ravni korak B0, dubina navoja H, prvi korak D), Fanuc G76 (bočni korak 60°).",
