"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Rupa s navojem u najdonjem dijelu: prolazna rupa završava gdje počinje najdonji dio; tamo nastaje rupa za navoj s navojem – tri zavoja dublje nego što vijak seže ili kroz cijeli dio. Ako se ispod tačke nalazi samo jedan dio, navoj dobiva od plohe nadalje. „Dužina prema dubini uvrtanja“ uzima sljedeću dužinu iz niza kojom vijak sjedi u navoju otprilike onoliko duboko koliko je debeo njegov navoj (okvirna vrijednost za čelik) – ali nikad duže nego što je dio debeo.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"rupa s navojem {0} – dubina uvijanja samo {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"rupa s navojem {0}, dubina uvijanja {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Rupa s navojem: buši se rupa za jezgru; navoj se prikazuje kao simbolički navoj na modelu i sa svojim nazivom na crtežu.",
