"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Jednaki prečnici daju cijev, različiti zarubljeni konus. Razvijeni oblik se računa na neutralnoj niti (unutrašnja ploha + K-faktor × debljina lima); kod valjanja leži bliže sredini lima nego kod savijanja na presi – uobičajen K-faktor je od 0,45 do 0,5. S pravilom za lim vrijede njegova debljina i K-faktor. Razmak šava ostaje otvoren na većem prečniku (0 = sučeljeno, u tijelu tada prorez od 0,01 mm).",
