"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Poluproizvod: nazivne mjere prema normi, izrezan na bilo koju dužinu. Nije svaka kombinacija mjere i debljine zida na zalihi kod svakog dobavljača. Cijev duž linije skice – i oko uglova i lukova – kreira naredba „Cijev“.",
