"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: na upravljačkoj jedinici omogućite prijenos podataka preko Etherneta (kao za TNCremo, LSV2, port 19000); zadani folder TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: port 21, folder npr. /_N_WKS_DIR ili /NC. Mrežni folder: putanja poput \\\\MASCHINE\\NC ili Z:\\NC. DNC: pretvarač kao TCP server (raw), obično port 4001; na upravljačkoj jedinici pokrenite „Vanjsko izvršavanje“, DNC ili TAPE.",
