"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"U zrcalnoj slici alat ide obrnuto: istosmjerno glodanje tamo postaje protusmjerno. Korekcija radijusa upravljanja također mijenja stranu.",
