"In diese Bibliothek kann nicht eingefügt werden – Dokument oder eigene Bibliothek wählen.":"U ovu biblioteku nije moguće umetati – odaberite dokument ili vlastitu biblioteku.",
"In diesem Setup sind Spannmittel gewählt: dann bleibt es beim vollständigen Rückzug.":"U ovom setupu su odabrana stezna sredstva: tada ostaje potpuno povlačenje.",
"In welcher Einheit STL-, OBJ-, 3MF- und PLY-Dateien ohne Angabe gelesen werden (je Netz änderbar)":"U kojoj se jedinici čitaju STL, OBJ, 3MF i PLY datoteke bez navedene jedinice (može se mijenjati po mreži)",
