"JSON kopieren":"Kopiraj JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Dva Q-parametra po operaciji na početku programa: prvi pomjera dubinu (DL, + = manje duboko), drugi bočni dodatak (DR, + = veći dodatak; djeluje samo uz korekciju radijusa u upravljanju RL/RR). Na mašini promijenite jedan broj umjesto traženja blokova.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Prva krivulja svake skice – otvorena ili zatvorena. Krivulje se povezuju omotačem (ploha bez debljine).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Jedna datoteka po ploči. Putanja ide u otpadu uz konturu, na pola širine reza (kod glodanja pola glodala); izrezi dolaze prije konture svog dijela, a svaka kontura počinje ulazom u rez iz otpada. Žaluzine se režu po svojoj liniji. Pridržni mostići: toliko mjesta po konturi ostaje neprerezano (laser, plazma, vodeni mlaz: mlaz se tu isključuje; glodanje: glodalo se podiže na pola debljine lima); konture kraće od 40 mm nemaju ih. „Upravljanje“ određuje čime se mlaz uključuje i isključuje; vrijeme probijanja u programu stoji kao G4, osim ako upravljanje samo probija. Nulta tačka je donji lijevi ugao ploče, kod glodanja je Z0 gornja strana lima. Program provjerite na mašini ili u NC simulatoru prije upotrebe.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Svi dijelovi po alatu (manje izmjena alata)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Svaka osa posebno: kliknite ivicu, ugao, plohu ili rupu. Osi koje nisu postavljene preuzimaju se iz tačke pripremka.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Svaka rupa se pojedinačno najavljuje svojim koordinatama (X/Y po rupi) – bez uzorka kruga rupa ili mreže.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Svaka operacija kao potprogram (LBL) na kraju programa, poziv s CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Izračunajte svaku varijantu i spremite kao STEP, STL ili 3MF (jedna ZIP datoteka)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Svaki krug skice je središte rupe. Buši se suprotno od normale skice (u materijal).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Svaki krug skice ponavlja se rotiran oko središta (u koordinatama skice) – krug na udaljenosti polumjera podjelnog kruga daje kružni raspored rupa.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Svaki krug skice postaje mreža: razmaci u X i Y skice (i negativni).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Svako vidljivo tijelo postaje karika s mrežom (STL, u metrima), masom i inercijom, svaki zglob zglob s osom i granicama. Trenutni položaj je nulti položaj. Sa nazivom paketa mreže u URDF-u stoje kao package://Name/meshes/…, inače kao relativna putanja.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Svaki # u tekstu skice zamjenjuje se brojem dopunjenim nulama (SN-#### → SN-{0}). Kod više dijelova u jednom stezanju svaki dio dobija sljedeći broj: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Svaki dio ima vlastitu nultu tačku u upravljanju (G54, G55 … ili broj referentne tačke u tabeli – Heidenhain ciklus 247). Sve nulte tačke prethodno postavite na mašini.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Svaka vlastita mjera i svaki okvir tolerancije dobija broj u krugu. Lista sadrži nazivnu mjeru, toleranciju, najveću i najmanju mjeru te polja za stvarnu vrijednost. Mjere bez vlastite tolerancije dobijaju opću toleranciju.",
"Jetzigen Stand festhalten":"Spremi trenutno stanje",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Sada tačka na drugom kraku.",
