"Kalibrieren: einen Abstand größer als 0 angeben.":"Kalibracija: unesite udaljenost veću od 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Kalibracija: kliknite prvu tačku na slici (Esc prekida).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Kalibracija: stvarna udaljenost između dvije tačke (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Kalibracija: kliknite dvije tačke na slici čija je udaljenost poznata i unesite stvarnu udaljenost – slika dobija ispravan razmjer.",
