"Kante im Blatt anklicken …":"Kliknite na ivicu na listu …",
"Kante projiziert":"Ivica projicirana",
"Kante {0} (Bogen R{1}, {2} mm)":"Ivica {0} (luk R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Ivica {0} (kružnica R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Ivica {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Ivica {0} je prekratka za jezičak",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Ivica {0}: ugao savijanja veći od 180° nije izvodljiv.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Ivica {0}: prirubnica na zakrivljenoj ivici – njen se rub pri oblikovanju sabija za {1} % (opasnost od nabora); razvijeni oblik je ovdje aproksimacija.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Ivica {0}: prirubnica na zakrivljenoj ivici – njen se rub pri oblikovanju rasteže za {1} % (opasnost od pukotina); razvijeni oblik je ovdje aproksimacija.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Ivica {0}: mjera prirubnice {1} mm manja je od savijanja ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Ivica {0}: luk je preuzak za ovu prirubnicu",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Ivica {0}: razmaci ne ostavljaju prirubnicu.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Ivica {0}: prirubnica presijeca liniju savijanja – neka završi prije savijanja pomoću „Razmak početak / kraj“",
"Kante {0}: die Lasche liegt in einer Biegezone":"Ivica {0}: prirubnica leži u zoni savijanja",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Ivica {0}: izrez pripada prirubnici koja ne postoji.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ivica {0}: izrez u prirubnici nalazi se {1} mm pored savijanja (manje od 2 × debljina lima) – deformiše se pri savijanju.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ivica {0}: izrez je {1} mm od savijanja (manje od 2 × debljina lima) – iskriviće se pri savijanju.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Ivica {0}: izrez viri izvan prirubnice.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Ivica {0}{1}: prirubnica {2} mm kraća je od 2 × debljina lima – na presi za savijanje jedva se može saviti.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Ivica {0}{1}: pregib {2} mm kraći je od 4 × debljina lima – teško se stišće.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Ivica {0}{1}: zatvoreni pregib (unutrašnji radijus {2} mm) – savija se u dva hoda i stišće; tvrdi materijali pritom pucaju na vanjskoj strani.",
"Kanten":"Ivice",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Ivice (prave se poklapaju, krugovi koncentrični)",
"Kanten abrunden: „Verrundung“ (F), einige Kanten anklicken, Radius z. B. 3 mm, OK.":"Zaoblite ivice: „Zaobljenje“ (F), kliknite nekoliko ivica, radijus npr. 3 mm, OK.",
"Kanten anklicken (erneut klicken entfernt).":"Kliknite ivice (ponovni klik uklanja).",
"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"Kliknite ivice da ih dodate ili uklonite – rezultat se odmah prikazuje na modelu. Ivice kliknute prije naredbe već su odabrane. Enter = U redu.",
"Kanten im Modell anklicken (erneut klicken entfernt)":"Kliknite ivice na modelu (ponovni klik uklanja)",
"Kanten wählen":"Odaberi ivice",
"Kanten wählen, die einen geschlossenen Rand bilden":"Odaberite ivice koje čine zatvoreni rub",
"Kantenglättung":"Izglađivanje rubova",
"Kantenhöhe":"Visina ivice",
"Kantenlänge":"Dužina ivice",
"Kantenlänge muss größer 0 sein":"Dužina ivice mora biti veća od 0",
"Kantenvarianten":"Varijante rubova",
"Kantungen je Ecke":"Savijanja po uglu",
"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Otpustite kapicu i odaberite „Kalibriraj nultu tačku“. Zatim isprobajte svaki smjer: traka se treba pomicati, a u mirovanju ostati u sivoj mrtvoj zoni.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Pomicanje kapice = pomicanje, pritisak/povlačenje = zumiranje, naginjanje i okretanje = rotiranje modela. U skicama samo pomicanje i zumiranje. SpaceMouse Pro/Enterprise: T, F, R = pogled odozgo, sprijeda, zdesna. Ako se ništa ne dogodi: kratko zatvorite 3Dconnexion upravljački program i ponovo se povežite.",
"Kegelmantel":"Konusni plašt",
