"Kegelrad: Zähnezahlen beider Räder angeben (mindestens 6)":"Konusni zupčanik: unesite broj zuba oba zupčanika (najmanje 6)",
"Kegelsenkung":"Konusno upuštanje",
"Kegelsenkungen":"Konusna upuštanja",
