"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Kontura s {0} tačaka – Okuma: G85 (LAP) s konturom G81…G80, Fanuc: G71 P…Q…. Upravljanje grubo obrađuje vlastitom podjelom; simulacija ovdje je WerkFab putanja.",
