"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Zaklopka na zaklopci: ugao + savija dalje u istom smjeru (U-profil, preklop od 180°), − u suprotnom smjeru (Z-stepenica, profil šešira). Pregib: ivica zaklopke presavija se za 180° na samu sebe – otvoreni s razmakom od jedne debljine lima, zatvoreni spljošteno stisnut; s − 180° leži na drugoj strani. Polje R je unutrašnji radijus samo ovog savijanja (prazno = kao kod lima). Za pregib direktno na ivici ploče postavite samu zaklopku na 180°. Stepenasto savijanje: dva savijanja jedno prema drugom (− 45° i + 45°) – ivica se nastavlja paralelno pomaknuta; pomak proizlazi iz dužine kosog komada i uglova.",
"Lasche {0}":"Prirubnica {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Prirubnice koje prelaze preko linije savijanja tamo su podijeljene i oslobođene.",
