"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Izdubljuje zatvorenu mrežu: dodaje se unutrašnji zid na udaljenosti debljine stijenke – štedi materijal i vrijeme štampe. Mjesta tanja od dvije debljine stijenke poslije se preklapaju; za štampu smolom oduzmite odvodnu rupu pomoću „Booleovo“.",
