"Mehrere Schrupp- oder Schlichtdurchgänge gibt es nur als Bahn":"Više prolaza grube ili završne obrade postoji samo kao putanja",
"Mehrere Teile in einer Aufspannung":"Više dijelova u jednom stezanju",
"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Više dubina rezanja i prolaz bez dodavanja postoje samo kao putanja",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Više povezanih ivica računa se kao jedna dionica: polumjer se mijenja od početka lanca do njegovog kraja, kontrolne tačke vrijede u % cijele dužine lanca. To računa veliko geometrijsko jezgro.",
"Mehrfachaufspannung":"Više dijelova",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Više dijelova: ovo upravljanje nema nultu tačku za dio {0} – izdat samo jedan dio",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Više dijelova: ovaj postprocesor nema pomak nulte tačke – odaberite „Vlastita nulta tačka za svaki dio“; izdat samo jedan dio",
"Meine Designs · {0}":"Moji dizajni · {0}",
"Meine Werkzeuge":"Moji alati",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Prijavljuje putanje koje režu dublje od modela na tom mjestu (valjkasti, čeoni, kuglasti i torusni glodači, glodala za skošenje i burgije sa svojim konusom; 3-osna kretanja). Prijavljuje se i rez kojeg nema u modelu – graviranje, rasterećenje ugla, džep samo iz skice.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Poruka na ekranu upravljanja: Fanuc i LinuxCNC kao (MSG, …), Sinumerik kao MSG(\"…\"), inače kao komentar.",
