"Nichts gefunden – anderes Wort, eine Norm (ISO 4762) oder ein Maß (M8, 6204, 33,7) versuchen.":"Ništa nije pronađeno – pokušajte s drugom riječi, normom (ISO 4762) ili mjerom (M8, 6204, 33,7).",
