"Noch kein Skript – eine .py-Datei oder einen Ordner laden.":"Još nema skripte – učitajte .py datoteku ili mapu.",
"Noch kein Wiederherstellungspunkt – der erste entsteht, sobald sich der Entwurf ändert und die eingestellte Zeit vergangen ist.":"Još nema tačke oporavka – prva nastaje čim se nacrt promijeni i prođe postavljeno vrijeme.",
"Noch kein Zusatzmodul – einen Ordner mit Zusatzmodul laden.":"Još nema dodatnog modula – učitajte mapu s dodatnim modulom.",
"Noch keine Designs gespeichert.":"Još nema spremljenih dizajna.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Još nema komentara. Pomoću + zabilježite bilješke uz dizajn.",
"Noch keine Konfiguration – erst Varianten anlegen oder eine Tabelle einlesen.":"Još nema konfiguracije – prvo kreirajte varijante ili učitajte tabelu.",
"Noch keine Konfiguration.":"Još nema konfiguracije.",
"Noch keine Operation":"Još nema operacije",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Još nema predložaka. Predložak sprema strategije sa svim postavkama (alat, podaci rezanja, visine, prolazi, povezivanje) za ponovnu upotrebu u drugim setupima i dizajnima.",
"Noch keine Werkzeuge im Dokument.":"U dokumentu još nema alata.",
