"Oberflächenzeichen und Bezüge bitte in der Vorder-, Drauf- oder Seitenansicht setzen.":"Oznake površine i baze postavite u prednji, gornji ili bočni pogled.",
"Oberhalb / Plusseite":"Iznad / plus strana",
