"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Džep na obodu iz zatvorenih kontura skice koja leži uzdužno uz osu obrtanja (unutrašnje konture ostaju kao ostrva). Skica se namotava na prečnik; pogonjena vretenasta glodala usmjerena prema osi uklanja materijal iznutra prema van (Z i C kreću se zajedno; Fanuc: cilindrična interpolacija G7.1). Glodalo ulazi po rampi duž najunutrašnjeg prstena.",
"Tasche gespiegelt":"Zrcaljeni džep",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Džep u čeonoj plohi iz zatvorenih kontura skice (unutrašnje konture ostaju kao otoci), pogonjenim vretenastim glodalom duž Z. Čisti se iznutra prema van; glodalo uranja po rampi duž najunutrašnje putanje i unutar jednog nivoa ostaje dolje. X i C se kreću zajedno (Fanuc: polarna interpolacija G12.1). Dubina od čeone plohe.",
"Tasche mit Insel":"Džep s otokom",
