"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"Gruba obrada uranjanjem: okomito uranjanje red po red – za duge alate i duboke šupljine",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"Dio 1 obično leži na nultoj tački (0, 0, 0). Do ostalih se dolazi pomakom nulte tačke (Heidenhain ciklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Prije svake promjene alat ide na sigurnu visinu.",
