"Verschiebt jede Fläche um den Abstand nach außen (negativ: nach innen) – für Spiel, Aufmaß oder ein Negativ. Kanten und Ecken bleiben scharf; sehr feine Stellen können sich beim Schrumpfen überschneiden.":"Pomjera svaku plohu prema van za zadanu udaljenost (negativno: prema unutra) – za zazor, dodatak ili negativ. Ivice i uglovi ostaju oštri; vrlo fini detalji se pri smanjivanju mogu preklopiti.",
