"Verschleiß":"Habanje",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Vijčani spoj: podloške i matica postavljaju se zajedno s vijkom u jednom koraku na svaku odabranu rupu. Debljina stezanja je dužina rupe – kroz više dijelova ako su im rupe u osi i naliježu jedna na drugu. S maticom se predlaže najkraća preferirana dužina kod koje vijak viri iz matice za dva navoja.",
