"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Koliko fino se tijela za STL, 3MF i Slicer rastavljaju na trouglove: odstupanje od prave površine kao udio veličine tijela. Mreže ostaju kakve jesu.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Koliko fino se cilindri, kugle i zaobljenja u prikazu sastoje od trouglova. Finije izgleda oblije, ali kod velikih modela duže traje proračun. Izvoz ima vlastitu postavku (3D štampa).",
"Wie im System":"Kao u sistemu",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Koliko dugo oštrica smije rezati prije nego što se zamijeni. Prozor „Vrijeme obrade“ iz toga izračunava koliko je komada još moguće.",
