"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Oblik zuba po metodi Tredgold (zamjenski cilindrični zupčanik na dopunskom konusu), ravni zubi. Veći kraj leži u osnovnoj ravni, zubi idu prema vrhu konusa. Za prikaz, 3D štampu i glodanje iz punog materijala; brušeni konusni zupčanici zahtijevaju podatke proizvođača.",
"Zahnrad: Stirnrad gerade / schräg / Pfeil, Hohlrad, Zahnstange, Kegelrad, Schnecke, Schneckenrad, Kettenrad":"Zupčanik: cilindrični ravni / kosi / strelasti, zupčanik s unutrašnjim ozubljenjem, zupčasta letva, konusni zupčanik, puž, pužni zupčanik, lančanik",
