"Zum Vereinen braucht es zwei Netzkörper.":"Za spajanje su potrebna dva mrežna tijela.",
"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Jezičci strše na slobodnom kraju zaklopke i ulaze u krojenje. „Utori kao skica“ kreira odgovarajuće utore tamo gdje jezičci stoje – po jednu skicu za ravan, svaki utor je sa svih strana veći od jezička za zazor. U ovoj skici nacrtajte obris protudijela i od njega napravite lim ili ekstruziju: utori postaju izrezi. Protudio leži na krajevima zaklopki; dužina jezička je obično jednaka njegovoj debljini.",
