"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"„+“ = alat će biti novi kreiran. Podaci rezanja su orijentacijske vrijednosti za tvrdi metal ({0}){1}; hlađenje: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Uklopiti jedno u drugo“ slaže krojeve u praznine i uvale susjednih dijelova te u njihove izreze (bez okretanja za 90° samo okrenuto za 180°); razmak se nikada ne smanjuje. Bez kvačice leže u redovima prema svom opisanom pravougaoniku. Uz „Skica + tijela“ nastaju ravna tijela debljine lima koja se u proizvodnji mogu izrezati 2D konturom.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Unutra/Vani“ zahtijeva zatvorene konture – otvorene krive glodati opcijom „Na krivoj“",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"„Provjeri“ prolazi kroz tok u malim vremenskim koracima i javlja kada se koja tijela sudaraju.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"„Završi skicu“ → Ekstruzija, Rotacija ili Rupa.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"„Skica“ → odaberite ravninu XY/XZ/YZ ili kliknite ravnu plohu.",
"„{0}“ als Netz übernommen – {1} Dreiecke. Der Körper ist ausgeblendet.":"„{0}“ preuzeto kao mreža – trouglova: {1}. Tijelo je sakriveno.",
"„{0}“ aus dem Link geöffnet – eine eigene Kopie, Änderungen bleiben auf diesem Rechner.":"„{0}“ otvoreno iz linka – vlastita kopija, izmjene ostaju na ovom računaru.",
